private static String unescape(String str) {
  StringBuilder outBuffer = new StringBuilder(str.length());
  for (int index = 0; index < str.length();) {
    char c = str.charAt(index++);
    if (c == '\\') {
      if (index >= str.length()) {
        outBuffer.append('\\');
        break;
      }
      c = str.charAt(index++);
      if (c == 't') {
        c = '\t';
      } else if (c == 'r') {
        c = '\r';
      } else if (c == 'n') {
        c = '\n';
      } else if (c == 'f') {
        c = '\f';
      } else {
        outBuffer.append('\\');
        index--;
      }
    }
    outBuffer.append(c);
  }
  return outBuffer.toString();
}
